import { Catalog, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Click a product when it\'s not in the context of a recommendation, search result, or category.  Use those specific events instead when appropriate. Subtypes:    **Click Recommendation:** If provided a personalization id, personalization provider id, and personalization content id in the Catalog event then the product link was provided by a product recommendation.   **Click Search Result:** If provided a search result ID in the Catalog event then the product link was provided by a search result. This also includes category product listings. 
*/
export type ClickProduct = {
    events: Array<Catalog | Identity | PartyIdentification | ErrorEvent>;
}

export class ClickProductBuilder {

    private clickProduct: ClickProduct = {
        events: []
    }

    private catalog!: Catalog;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCatalog(catalog: Catalog) : ClickProductBuilder {
        this.catalog = catalog;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : ClickProductBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : ClickProductBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : ClickProductBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : ClickProduct {
        if(this.catalog) {
            this.clickProduct.events.push(this.catalog);
        }
        if(this.errorEvent) {
            this.clickProduct.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.clickProduct.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.clickProduct.events.push(this.partyIdentification);
        }

        return this.clickProduct;
    }
}
